function validate([edges, bob, amount]) {
  if (!Array.isArray(edges) || !Array.isArray(amount)) return 'edges and amount must be arrays.';
  const n = amount.length;
  if (n < 2 || n > 100000) return 'The tree needs 2 to 10^5 nodes.';
  if (edges.length !== n - 1) return 'edges must have exactly n - 1 pairs.';
  if (!Number.isInteger(bob) || bob < 1 || bob >= n) return 'bob is a node from 1 to n - 1.';
  if (amount.some(v => !Number.isInteger(v) || v % 2 !== 0 || v < -10000 || v > 10000)) return 'Each amount is an even integer from -10^4 to 10^4.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = x => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const e of edges) {
    if (!Array.isArray(e) || e.length !== 2) return 'Each edge is a pair [a, b].';
    const [a, b] = e;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= n || b >= n) return 'Edge endpoints must be nodes 0 to n - 1.';
    if (a === b) return 'An edge cannot join a node to itself.';
    const ra = find(a), rb = find(b);
    if (ra === rb) return 'edges must form a tree (no cycles).';
    root[ra] = rb;
  }
  return null;
}

