function mostProfitablePath(edges, bob, amount) {
  const n = amount.length;
  const graph = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) {
    graph[a].push(b);
    graph[b].push(a);
  }
  const parent = new Array(n).fill(-1);
  const depth = new Array(n).fill(0);
  const order = [];
  const stack = [0];
  while (stack.length > 0) {
    const node = stack.pop();
    order.push(node);
    for (const next of graph[node]) {
      if (next !== parent[node]) {
        parent[next] = node;
        depth[next] = depth[node] + 1;
        stack.push(next);
      }
    }
  }
  const bobTime = new Array(n).fill(Infinity);
  let time = 0;
  for (let node = bob; node !== -1; node = parent[node]) {
    bobTime[node] = time;
    time++;
  }
  const income = new Array(n).fill(0);
  let best = -Infinity;
  for (const node of order) {
    let gain = 0;
    if (depth[node] < bobTime[node]) {
      gain = amount[node];
    } else if (depth[node] === bobTime[node]) {
      gain = amount[node] / 2;
    }
    income[node] = (node === 0 ? 0 : income[parent[node]]) + gain;
    if (node !== 0 && graph[node].length === 1) {
      best = Math.max(best, income[node]);
    }
  }
  return best;
}

