function mostProfitablePath(edges, bob, amount) {
  const n = amount.length;
  const adj = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }
  const par = new Array(n).fill(-2);
  par[0] = -1;
  const queue = [0];
  for (let h = 0; h < queue.length; h++) {
    const u = queue[h];
    for (const v of adj[u]) if (par[v] === -2) { par[v] = u; queue.push(v); }
  }
  const bobPath = [];
  for (let u = bob; u !== -1; u = par[u]) bobPath.push(u);
  let best = -Infinity;
  for (let leaf = 1; leaf < n; leaf++) {
    if (adj[leaf].length !== 1) continue;
    const alicePath = [];
    for (let u = leaf; u !== -1; u = par[u]) alicePath.unshift(u);
    const opened = new Set();
    let total = 0;
    const steps = Math.max(alicePath.length, bobPath.length);
    for (let t = 0; t < steps; t++) {
      const a = alicePath[Math.min(t, alicePath.length - 1)];
      const b = bobPath[Math.min(t, bobPath.length - 1)];
      if (!opened.has(a)) total += a === b ? amount[a] / 2 : amount[a];
      opened.add(a);
      opened.add(b);
    }
    best = Math.max(best, total);
  }
  return best;
}

