function generate(rand, size) {
  const n = size === 'large' ? 2000 : 2 + Math.floor(rand() * 8);
  const chainy = rand() < 0.3;
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [label[i], label[j]] = [label[j], label[i]]; }
  const edges = [];
  for (let i = 1; i < n; i++) {
    const p = chainy ? Math.max(0, i - 1 - Math.floor(rand() * 2)) : Math.floor(rand() * i);
    edges.push(rand() < 0.5 ? [label[p], label[i]] : [label[i], label[p]]);
  }
  for (let i = edges.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  const bob = 1 + Math.floor(rand() * (n - 1));
  const half = size === 'large' || rand() < 0.3 ? 5000 : 5;
  const amount = Array.from({ length: n }, () => 2 * (Math.floor(rand() * (2 * half + 1)) - half));
  return [edges, bob, amount];
}
